theorem hypothesisError_eq_add {P : Measure α} {h c : Set α}
    (hh : MeasurableSet h) (hc : MeasurableSet c) :
    hypothesisError P h c = falsePositiveError P h c + falseNegativeError P h c

theorem mem_versionSpace_iff {m : ℕ} {C : ConceptClass α β}
    {S : LabeledSample α β m} {h : α → β} :
    h ∈ VersionSpace C S ↔ h ∈ C ∧ ∀ i : Fin m, h (S i).1 = (S i).2

theorem Realizable.versionSpace_nonempty {m : ℕ} {C : ConceptClass α β}
    {S : LabeledSample α β m} (h : Realizable C S) :
    (VersionSpace C S).Nonempty

theorem inter_mem_versionSpaces {C U V : ConceptClass α β}
    (hU : U ∈ VersionSpaces C) (hV : V ∈ VersionSpaces C) :
    U ∩ V ∈ VersionSpaces C

theorem trans [Fintype α] {p q r : PMF α} {ε δ : ℝ≥0}
    (hpq : StatisticallyClose p q ε) (hqr : StatisticallyClose q r δ) :
    StatisticallyClose p r (ε + δ)

theorem bind [Fintype α] [Fintype β] {p q : PMF α} {ε : ℝ≥0}
    (h : StatisticallyClose p q ε) (kernel : α → PMF β) :
    StatisticallyClose (p.bind kernel) (q.bind kernel) ε

theorem map [Fintype α] [Fintype β] {p q : PMF α} {ε : ℝ≥0}
    (h : StatisticallyClose p q ε) (f : α → β) :
    StatisticallyClose (p.map f) (q.map f) ε
